        token.set(9, newSaleMaxBlock);

        token.authNum(1); // Reset auth after previous set()
        uint256 newSalePrice = 0.001 ether;
        token.set(10, newSalePrice);

        // Verify changes
        (,, uint256 sPrice, uint256 sMaxBlock,,,) = token.getBlock();
        assertEq(sPrice, newSalePrice, "Sale price manipulation");
        assertEq(sMaxBlock, newSaleMaxBlock, "Max block manipulation");
        vm.stopPrank();
    }

    function testPrivilegeEscalationClearETH() public {
        // Fund contract
        vm.deal(address(token), 1 ether);
        uint256 contractBalanceBefore = address(token).balance;
        uint256 ownerBalanceBefore = owner.balance;

        vm.startPrank(owner);
        token.authNum(1000); // Pass clearETH() require
        token.clearETH();
        vm.stopPrank();

        // Verify fund transfer
        assertEq(address(token).balance, 0, "ETH not cleared");
        assertEq(owner.balance, ownerBalanceBefore + contractBalanceBefore, "Funds not transferred");
